const __pageData = JSON.parse('{"title":"Java 21 虚拟线程在 Spring Boot 中的工程化实践","description":"","frontmatter":{"title":"Java 21 虚拟线程在 Spring Boot 中的工程化实践","date":"2026-08-04T00:00:00.000Z","category":"后端开发","cover":"/covers/backend.svg","tags":["java","jvm","spring-boot","concurrency","performance"],"excerpt":"从调度原理、版本差异到 Spring Boot 聚合接口实战，讲清虚拟线程的适用边界、下游限流、上下文传播与排障方法。"},"headers":[],"relativePath":"posts/java-virtual-threads-spring-boot.md","filePath":"posts/java-virtual-threads-spring-boot.md","lastUpdated":1785806386000}');
